import XCTest

/// The "current" side is a pre-baked `CodeArtifact` fixture (`seeded-with-added.json`, generated by
/// `FixtureArtifactGeneratorTests`) that already includes an `Added` type, and the "HEAD" comparison
/// side is a separate pre-baked fixture (`comparison-HEAD.json`) without it — so comparing the two
/// produces a real, visible delta without a real git commit or a real parse. The business-logic claim
/// this used to prove end-to-end (comparing against HEAD excludes an uncommitted addition) is now
/// covered directly at the ViewModel layer by
/// `PullRequestComparisonTests.comparingAgainstHEADExcludesAnUncommittedAddition`; this journey only
/// verifies the panel renders and interacts correctly once that state exists.
@MainActor
final class CompareGitRevisionTests: UIJourneyTestCase {
    private static let projectID = "11111111-1111-1111-1111-111111111111"
    private static let codebaseID = "22222222-2222-2222-2222-222222222222"

    private var comparator: ScreenshotComparator {
        ScreenshotComparator(goldenDirectory: URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .appendingPathComponent("__Snapshots__"))
    }

    func testComparingAgainstHEADShowsAnAddedTypeAfterAnUncommittedEdit() throws {
        app.rotateToLandscapeOnIPad()
        app.launchWithFixture("seeded") { app, destination in
            let artifactsDir = destination.appendingPathComponent("artifacts")
            app.launchEnvironment["ACAI_UITEST_CODEBASE_ARTIFACTS"] = app.environmentRecords([
                [Self.codebaseID, artifactsDir.appendingPathComponent("seeded-with-added.json").path]
            ])
            app.launchEnvironment["ACAI_UITEST_COMPARISON_ARTIFACTS"] = app.environmentRecords([
                [Self.codebaseID, "HEAD", artifactsDir.appendingPathComponent("comparison-HEAD.json").path]
            ])
        }

        let browser = ProjectBrowserScreen(app: app)
        let projectRow = browser.projectRow(id: Self.projectID)
        XCTAssertTrue(projectRow.waitForExistence(timeout: 10))

        let detail = ProjectDetailScreen(app: app)
        let codebaseRow = detail.codebaseRow(id: Self.codebaseID)
        // A sidebar re-render racing this tap can invalidate `projectRow` between find and tap.
        projectRow.tapUntil(codebaseRow)
        XCTAssertTrue(codebaseRow.waitForExistence(timeout: 10))
        codebaseRow.tap()

        let codebaseDetail = CodebaseDetailScreen(app: app)
        XCTAssertTrue(codebaseDetail.reindexButton.waitForExistence(timeout: 10))
        codebaseDetail.reindexButton.tap()

        let classDiagramButton = codebaseDetail.diagramButton(type: "class")
        XCTAssertTrue(classDiagramButton.waitForExistence(timeout: 30), "the codebase never finished indexing")
        classDiagramButton.tap()

        let diagram = ClassDiagramScreen(app: app)
        diagram.tapFitToView()
        XCTAssertTrue(diagram.typeNode(named: "Added").waitForExistence(timeout: 10),
                      "the uncommitted edit should still be visible on the current (working-tree) side")

        XCTAssertTrue(diagram.compareButton.waitForExistence(timeout: 10))
        diagram.openCompare()
        comparator.validate(
            viewType: "ClassDiagram", state: "comparePanelOpen",
            screenshot: app.screenshotAfterAnimationsIdle(), testCase: self
        )

        diagram.chooseCompareRef("HEAD")
        let loaded = diagram.compareLoadedIndicator.waitForExistence(timeout: 10)
        let errorExists = diagram.compareErrorIndicator.exists
        let errorMessage = errorExists ? diagram.compareErrorIndicator.label : "(no error shown)"
        XCTAssertTrue(loaded, "comparison snapshot never finished loading: \(errorMessage)")
        XCTAssertFalse(errorExists, errorMessage)

        comparator.validate(
            viewType: "ClassDiagram", state: "deltaComparison",
            screenshot: app.screenshotAfterAnimationsIdle(), testCase: self
        )

        // Clear disables the comparison directly — there's no "None" row to pick instead.
        diagram.compareClearButton.tap()
        XCTAssertFalse(diagram.compareLoadedIndicator.exists, "Clear should turn the comparison back off")
    }
}
